.mmc-wrap{max-width:1500px}.mmc-lead{font-size:16px;color:#50575e}.mmc-cards{display:grid;grid-template-columns:repeat(4,minmax(160px,1fr));gap:16px;margin:20px 0}.mmc-cards-5{grid-template-columns:repeat(5,minmax(150px,1fr))}.mmc-card,.mmc-panel{background:#fff;border:1px solid #dcdcde;border-radius:10px;padding:18px;box-shadow:0 1px 2px rgba(0,0,0,.04)}.mmc-card span{display:block;color:#646970}.mmc-card strong{display:block;font-size:30px;margin-top:6px;color:#102a43}.mmc-card small{display:block;margin-top:6px;color:#70757a}.mmc-panel{margin:18px 0}.mmc-flow{padding:14px;background:#f6f7f7;border-left:4px solid #2271b1;font-weight:600;line-height:1.7}.mmc-form-grid{display:grid;grid-template-columns:repeat(2,minmax(220px,1fr));gap:16px}.mmc-form-grid label{font-weight:600}.mmc-form-grid input,.mmc-form-grid textarea,.mmc-form-grid select{display:block;width:100%;margin-top:6px}.mmc-span-2{grid-column:span 2}.mmc-timeline{display:grid;grid-template-columns:repeat(4,minmax(180px,1fr));gap:12px;margin:20px 0}.mmc-step{background:#fff;border:1px solid #dcdcde;border-radius:10px;padding:14px;display:grid;grid-template-columns:32px 1fr;align-items:center;gap:8px}.mmc-step b{width:28px;height:28px;border-radius:50%;background:#102a43;color:#fff;display:flex;align-items:center;justify-content:center}.mmc-step span{font-weight:700}.mmc-step small{grid-column:2;color:#777}.mmc-inline-form{display:flex;gap:12px;align-items:end;flex-wrap:wrap}.mmc-inline-form select{min-width:420px}.mmc-check-grid{display:grid;grid-template-columns:repeat(4,minmax(160px,1fr));gap:10px;margin:14px 0}.mmc-check-grid label{background:#f6f7f7;border:1px solid #dcdcde;border-radius:7px;padding:9px}.mmc-block-label{display:block;margin:12px 0;font-weight:600}.mmc-block-label input{width:100%;max-width:700px;display:block;margin-top:6px}.mmc-grid-2{display:grid;grid-template-columns:1fr 1fr;gap:18px}.mmc-hero-panel{display:flex;justify-content:space-between;align-items:center;background:#f0f6fc;border-color:#72aee6}.mmc-hero-panel h2{margin:.2em 0}.mmc-hero-panel small{color:#646970;font-weight:600}@media(max-width:1100px){.mmc-cards-5{grid-template-columns:repeat(3,1fr)}.mmc-check-grid{grid-template-columns:repeat(3,1fr)}}@media(max-width:900px){.mmc-cards,.mmc-timeline,.mmc-form-grid,.mmc-grid-2{grid-template-columns:1fr 1fr}.mmc-span-2{grid-column:span 2}.mmc-check-grid{grid-template-columns:repeat(2,1fr)}}@media(max-width:600px){.mmc-cards,.mmc-cards-5,.mmc-timeline,.mmc-form-grid,.mmc-grid-2,.mmc-check-grid{grid-template-columns:1fr}.mmc-span-2{grid-column:span 1}.mmc-inline-form select{min-width:100%;width:100%}.mmc-hero-panel{display:block}}
.mmc-action-row{display:flex;gap:10px;align-items:center;flex-wrap:wrap;margin-top:16px;padding-top:14px;border-top:1px solid #dcdcde}.mmc-action-row form{margin:0}.mmc-doc-preview{width:100%;min-height:430px;font-family:ui-monospace,SFMono-Regular,Menlo,Consolas,monospace;line-height:1.55;background:#f6f7f7}.mmc-finance-form{display:flex;gap:6px;align-items:center;flex-wrap:wrap}.mmc-finance-form .small-text{width:130px}.mmc-badge{display:inline-block;padding:3px 8px;border-radius:999px;background:#f0f0f1;font-size:12px;font-weight:600}
.mmc-issues { margin-left: 1.4em; list-style: disc; }
.mmc-issues li { margin: 4px 0; }
.mmc-wrap table form { margin: 0; }
.mmc-wrap table input[type="url"] { max-width: 260px; }
.mmc-wrap textarea{width:100%}.mmc-wrap details{margin:12px 0;padding:10px;background:#f6f7f7;border-radius:8px}.mmc-wrap details summary{cursor:pointer;font-weight:600}

.mmc-table-scroll{overflow:auto;max-height:650px;border:1px solid #dcdcde;margin-top:12px}.mmc-table-scroll table{border:0}.mmc-table-scroll thead th{position:sticky;top:0;background:#fff;z-index:2}.mmc-wrap code{word-break:break-all}
/* v1.1 Executive Dashboard */
.mmc-dashboard-heading{display:flex;justify-content:space-between;align-items:center;gap:20px}.mmc-dashboard-heading h1{margin-bottom:4px}.mmc-dashboard-clock{text-align:right}.mmc-dashboard-clock strong,.mmc-dashboard-clock span{display:block}.mmc-dashboard-clock strong{font-size:18px}.mmc-dashboard-clock span{color:#646970;margin-top:3px}
.mmc-kpi-grid{display:grid;grid-template-columns:repeat(7,minmax(145px,1fr));gap:12px;margin:20px 0}.mmc-kpi{background:#fff;border:1px solid #dcdcde;border-top:4px solid #72aee6;border-radius:10px;padding:14px;min-height:105px}.mmc-kpi>span{display:block;color:#646970;font-size:12px;font-weight:700;min-height:30px}.mmc-kpi>strong{display:block;font-size:23px;line-height:1.15;color:#102a43;margin:5px 0}.mmc-kpi>small{display:block;color:#646970}.mmc-kpi-success{border-top-color:#00a32a}.mmc-kpi-warning{border-top-color:#dba617}.mmc-kpi-danger{border-top-color:#d63638}.mmc-kpi-muted{border-top-color:#a7aaad}.mmc-kpi-info{border-top-color:#2271b1}
.mmc-dashboard-strip{display:flex;gap:24px;align-items:center;padding:10px 14px;margin:-6px 0 18px;background:#f6f7f7;border:1px solid #dcdcde;border-radius:8px}.mmc-dashboard-strip span{color:#50575e}.mmc-dashboard-strip strong{color:#1d2327}
.mmc-alert-panel{border-left:4px solid #d63638}.mmc-alert-list{display:grid;grid-template-columns:1fr 1fr;gap:8px}.mmc-alert{display:flex;flex-direction:column;text-decoration:none;background:#f6f7f7;border-left:4px solid #dba617;padding:10px 12px;color:#1d2327}.mmc-alert:hover{background:#fff}.mmc-alert.mmc-risk-critical{border-left-color:#d63638}.mmc-alert strong{margin-bottom:3px}.mmc-alert span{color:#50575e}
.mmc-panel-head{display:flex;justify-content:space-between;align-items:flex-start}.mmc-panel-head h2{margin-bottom:4px}.mmc-panel-head p{margin-top:0;color:#646970}.mmc-dashboard-filters{display:flex;gap:8px;align-items:center;flex-wrap:wrap;margin:12px 0}.mmc-dashboard-filters input[type=search]{min-width:220px}.mmc-filter-check{display:flex;gap:5px;align-items:center;padding:5px 8px;background:#f6f7f7;border-radius:5px}.mmc-dashboard-table{max-height:760px}.mmc-dashboard-table th{white-space:nowrap}.mmc-dashboard-table td{vertical-align:top;min-width:105px}.mmc-dashboard-table td:first-child{min-width:160px}
.mmc-status-badge,.mmc-risk-pill{display:inline-block;padding:4px 8px;border-radius:999px;font-size:11px;font-weight:700;white-space:nowrap}.mmc-status-badge{background:#e5f0fa;color:#135e96}.mmc-risk-pill.mmc-risk-critical{background:#fbeaea;color:#b32d2e}.mmc-risk-pill.mmc-risk-high{background:#fcf0d4;color:#8a5d00}.mmc-risk-pill.mmc-risk-ok{background:#e7f5e8;color:#007017}.mmc-risk-pill.mmc-risk-info{background:#e5f0fa;color:#135e96}.mmc-risk-line{padding:4px 0;border-bottom:1px solid #dcdcde;font-size:12px}.mmc-risk-line:last-child{border-bottom:0}.mmc-risk-line.mmc-risk-critical{color:#b32d2e;font-weight:700}.mmc-risk-line.mmc-risk-high{color:#8a5d00}.mmc-quick-actions{display:grid;grid-template-columns:1fr 1fr;gap:4px}.mmc-quick-actions a{text-decoration:none;background:#f0f0f1;border-radius:5px;padding:5px 7px;text-align:center;font-size:12px}.mmc-quick-actions a:hover{background:#2271b1;color:#fff}.mmc-muted{color:#8c8f94}.mmc-text-danger{color:#b32d2e!important}.mmc-text-warning{color:#8a5d00!important}
@media(max-width:1500px){.mmc-kpi-grid{grid-template-columns:repeat(4,minmax(160px,1fr))}}@media(max-width:1000px){.mmc-kpi-grid{grid-template-columns:repeat(2,1fr)}.mmc-alert-list{grid-template-columns:1fr}}@media(max-width:600px){.mmc-dashboard-heading{display:block}.mmc-dashboard-clock{text-align:left;margin-top:8px}.mmc-kpi-grid{grid-template-columns:1fr}.mmc-dashboard-strip{display:block}.mmc-dashboard-strip span{display:block;margin:4px 0}}
/* v1.3 Kurulum & Sağlık / veri hazırlık UX */
.mmc-readiness-notice{margin:14px 0!important;padding:10px 12px!important}.mmc-readiness-notice .button{margin-left:8px}
.mmc-readiness-box{display:flex;justify-content:space-between;align-items:center;gap:18px;padding:16px 18px;border-radius:10px;margin:16px 0;border:1px solid #dcdcde;background:#fff}.mmc-readiness-box strong{font-size:15px}.mmc-readiness-box span{color:#50575e}.mmc-readiness-critical{border-left:5px solid #d63638;background:#fff8f8}
.mmc-health-summary{display:grid;grid-template-columns:repeat(4,minmax(150px,1fr));gap:12px;margin:18px 0}.mmc-health-count{background:#fff;border:1px solid #dcdcde;border-radius:10px;padding:16px;border-top:4px solid #a7aaad}.mmc-health-count strong{display:block;font-size:28px;line-height:1;color:#102a43}.mmc-health-count span{display:block;margin-top:7px;color:#50575e;font-weight:600}.mmc-health-count.mmc-health-critical{border-top-color:#d63638}.mmc-health-count.mmc-health-warning{border-top-color:#dba617}.mmc-health-count.mmc-health-ok{border-top-color:#00a32a}.mmc-health-count.mmc-health-info{border-top-color:#2271b1}
.mmc-health-pill{display:inline-block;padding:4px 8px;border-radius:999px;font-size:11px;font-weight:700;white-space:nowrap}.mmc-health-pill.mmc-health-critical{background:#fbeaea;color:#b32d2e}.mmc-health-pill.mmc-health-warning{background:#fcf0d4;color:#8a5d00}.mmc-health-pill.mmc-health-ok{background:#e7f5e8;color:#007017}.mmc-health-pill.mmc-health-info{background:#e5f0fa;color:#135e96}.mmc-health-table td{vertical-align:middle}.mmc-checklist li{margin:0 0 9px 18px}.mmc-form-grid small.description{display:block;margin-top:5px;font-weight:400}.mmc-timeline .mmc-step small{line-height:1.4;color:#646970}
@media(max-width:900px){.mmc-health-summary{grid-template-columns:1fr 1fr}.mmc-readiness-box{display:block}.mmc-readiness-box .button{margin-top:12px}}@media(max-width:600px){.mmc-health-summary{grid-template-columns:1fr}}
